import { focusRing } from "@/lib/beton/shared";
import { tv, type VariantProps } from "@/lib/beton/tv";

export const tabs = tv({
  slots: {
    root: "flex w-full",
    list: "relative flex",
    tab: [
      "relative flex shrink-0 cursor-pointer select-none items-center justify-center gap-2",
      "border-3 border-transparent font-display font-extrabold uppercase tracking-wide text-foreground",
      "hover:underline",
      "data-active:border-border data-active:bg-raised",
      "data-disabled:cursor-not-allowed data-disabled:text-disabled-foreground data-disabled:no-underline",
      focusRing,
    ],
    panel: "min-w-0 flex-1 p-6 outline-none",
    indicator: [
      "absolute bg-primary",
      "transition-[translate,width,height] duration-100 ease-linear motion-reduce:transition-none",
    ],
  },
  variants: {
    orientation: {
      horizontal: {
        root: "flex-col",
        list: "flex-row flex-wrap border-b-3 border-border",
        tab: "-mb-[3px] data-active:border-b-surface",
        indicator: "top-0 left-0 h-1 w-(--active-tab-width) translate-x-(--active-tab-left)",
      },
      vertical: {
        root: "flex-row",
        list: "flex-col border-r-3 border-border",
        tab: "-mr-[3px] justify-start data-active:border-r-surface",
        indicator: "top-0 left-0 h-(--active-tab-height) w-1 translate-y-(--active-tab-top)",
      },
    },
    size: {
      sm: { tab: "min-h-11 px-3 text-sm", panel: "p-4" },
      md: { tab: "min-h-12 px-4 text-base", panel: "p-6" },
      lg: { tab: "min-h-14 px-5 text-lg", panel: "p-8" },
    },
  },
  defaultVariants: {
    orientation: "horizontal",
    size: "md",
  },
});

export type TabsVariants = VariantProps<typeof tabs>;

"use client";

import { Tabs as BaseTabs } from "@base-ui/react/tabs";
import { tabs, type TabsVariants } from "@/lib/beton/recipes/tabs.recipe";
import { createContext, useContext } from "react";

interface TabsState {
  styles: ReturnType<typeof tabs>;
  size: NonNullable<TabsVariants["size"]>;
}

const TabsContext = createContext<TabsState>({ styles: tabs(), size: "md" });

function useStyles() {
  return useContext(TabsContext).styles;
}

export interface TabsProps extends Omit<BaseTabs.Root.Props, "className">, TabsVariants {
  className?: string;
}

function TabsRoot({ size = "md", orientation = "horizontal", className, ...props }: TabsProps) {
  const styles = tabs({ size, orientation });
  return (
    <TabsContext.Provider value={{ styles, size }}>
      <BaseTabs.Root
        {...props}
        orientation={orientation}
        className={styles.root({ class: className })}
      />
    </TabsContext.Provider>
  );
}

export interface TabsListProps extends Omit<BaseTabs.List.Props, "className"> {
  className?: string;
  /** Draw the moving bar that follows the active tab. On by default. */
  indicator?: boolean;
}

function TabsList({ className, children, indicator = true, ...props }: TabsListProps) {
  const styles = useStyles();
  return (
    <BaseTabs.List {...props} className={styles.list({ class: className })}>
      {children}
      {indicator ? <BaseTabs.Indicator className={styles.indicator()} /> : null}
    </BaseTabs.List>
  );
}

export interface TabProps extends Omit<BaseTabs.Tab.Props, "className"> {
  className?: string;
}

function Tab({ className, ...props }: TabProps) {
  const { styles, size } = useContext(TabsContext);
  return <BaseTabs.Tab {...props} data-size={size} className={styles.tab({ class: className })} />;
}

export interface TabsPanelProps extends Omit<BaseTabs.Panel.Props, "className"> {
  className?: string;
}

function TabsPanel({ className, ...props }: TabsPanelProps) {
  return <BaseTabs.Panel {...props} className={useStyles().panel({ class: className })} />;
}

/** Switch between views that sit at the same level. */
export const Tabs = Object.assign(TabsRoot, {
  List: TabsList,
  Tab,
  Panel: TabsPanel,
});
